# ---------- writer ----------
IDS = []
batches = json.load(open(os.path.join(BASE, "batches.json"), encoding="utf-8"))
for k in ("B10", "B11", "B12"):
    IDS += batches[k]
assert len(IDS) == 60, len(IDS)
assert set(IDS) == set(C.keys()), (set(IDS) ^ set(C.keys()))

total_bytes = 0
trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in IDS:
    pred, kern, timing, conf, (cm, ru, di), treason = C[cid]
    basis = ("tradition=liuyao\nsystems_used=六爻纳甲\n" + kern + "\n" + timing)
    obj = {
        "case_id": cid,
        "prediction_text": pred,
        "basis": basis,
        "confidence": conf,
        "trigger": {"changed_main": bool(cm), "reserve_used": bool(ru), "disputed": bool(di), "reason": treason},
    }
    p = os.path.join(OUT, cid + ".json")
    data = json.dumps(obj, ensure_ascii=False, indent=1).encode("utf-8")
    with open(p, "wb") as f:
        f.write(data)
    total_bytes += len(data)
    trig["changed_main"] += int(cm); trig["reserve_used"] += int(ru); trig["disputed"] += int(di)
print("written", len(IDS), "bytes", total_bytes, "trig", trig)
